 func parseValue(field reflect.Value, sf reflect.StructField, value string, funcMap map[reflect.Type]ParserFunc) (interface{}, error) {
 	// Determine the actual type to parse into (dereference pointer)
 	fieldType := field.Type()
 	if fieldType.Kind() == reflect.Ptr {
 		fieldType = fieldType.Elem()
 	}

 	// Check custom funcMap by type
 	if parserFunc, ok := funcMap[fieldType]; ok {
 		val, err := parserFunc(value)
 		if err != nil {
 			return nil, newParseError(sf, err)
 		}
 		return val, nil
 	}

 	// Obtain an addressable value of the target type to check interfaces
 	refVal := reflect.New(fieldType)

 	// encoding.TextUnmarshaler
 	if tu, ok := refVal.Interface().(encoding.TextUnmarshaler); ok {
 		if err := tu.UnmarshalText([]byte(value)); err != nil {
 			return nil, newParseError(sf, err)
 		}
 		return refVal.Elem().Interface(), nil
 	}

 	// Check built-in parsers by kind
 	kind := fieldType.Kind()
 	if parserFunc, ok := defaultBuiltInParsers[kind]; ok {
 		val, err := parserFunc(value)
 		if err != nil {
 			return nil, newParseError(sf, err)
 		}
 		return val, nil
 	}

 	return nil, newNoParserError(sf)
 }

 func handleSlice(field reflect.Value, sf reflect.StructField, value string, funcMap map[reflect.Type]ParserFunc) error {
 	var separator string
