 	parts := strings.Split(value, separator)

 	// Determine element type
 	sliceType := field.Type()
 	isArray := field.Kind() == reflect.Array
 	elemType := sliceType.Elem()
 	isElemPtr := elemType.Kind() == reflect.Ptr
